{"path": "/tmp/sv-740fd47a6e5e4fc2bc228148c89e5314/Components/Pages/Chat.razor", "file_text": "@page "/chat"
@using sv_740fd47a6e5e4fc2bc228148c89e5314.Services
@using sv_740fd47a6e5e4fc2bc228148c89e5314.Components.Chat
@inject IChatService ChatService
@rendermode InteractiveServer

<div class="chat-layout @(IsThreadOpen ? "thread-open" : "")">
    <ChannelSidebar Channels="channels"
                    ActiveChannelId="selectedChannelId"
                    OnChannelSelected="SelectChannel" />

    <MessageArea CurrentChannel="SelectedChannel"
                 Messages="messages"
                 ThreadReplyCounts="threadReplyCounts"
                 IsLoadingOlder="isLoadingOlder"
                 OnOpenThread="OpenThread"
                 OnReact="HandleReaction"
                 OnLoadOlder="LoadOlderMessages"
                 OnSendMessage="SendMessage" />

    @if (IsThreadOpen)
    {
        <ThreadPanel RootMessage="threadRootMessage"
                     Replies="threadReplies"
                     OnClose="CloseThread"
                     OnSendReply="SendThreadReply" />
    }
</div>

@code {
    private List<Channel> channels = [];
    private List<Message> messages = [];
    private Dictionary<int, int> threadReplyCounts = [];
    private int selectedChannelId;
    private bool isLoadingOlder;
    private const int PageSize = 30;

    // Thread state
    private Message? threadRootMessage;
    private List<Message> threadReplies = [];

    private bool IsThreadOpen => threadRootMessage is not null;
    private Channel? SelectedChannel => channels.FirstOrDefault(c => c.Id == selectedChannelId);

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await SelectChannel(channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        selectedChannelId = channelId;
        messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        threadReplyCounts = await BuildThreadReplyCounts();
        await ChatService.MarkChannelReadAsync(channelId);

        // Update the unread count locally
        var idx = channels.FindIndex(c => c.Id == channelId);
        if (idx >= 0)
        {
            var ch = channels[idx];
            channels[idx] = ch with { UnreadCount = 0 };
        }
    }

    private async Task LoadOlderMessages()
    {
        if (isLoadingOlder) return;
        isLoadingOlder = true;

        var older = await ChatService.GetMessagesAsync(selectedChannelId, messages.Count, PageSize);
        if (older.Count > 0)
        {
            messages.InsertRange(0, older);
            var newCounts = await BuildThreadReplyCounts();
            foreach (var kvp in newCounts)
            {
                threadReplyCounts[kvp.Key] = kvp.Value;
            }
        }

        isLoadingOlder = false;
    }

    private async Task SendMessage(string content)
    {
        var message = await ChatService.SendMessageAsync(selectedChannelId, content, null);
        messages.Add(message);
    }

    private async Task OpenThread(int messageId)
    {
        threadRootMessage = messages.FirstOrDefault(m => m.Id == messageId);
        if (threadRootMessage is not null)
        {
            threadReplies = await ChatService.GetThreadAsync(messageId);
        }
    }

    private void CloseThread()
    {
        threadRootMessage = null;
        threadReplies = [];
    }

    private async Task SendThreadReply(string content)
    {
        if (threadRootMessage is null) return;
        var reply = await ChatService.SendMessageAsync(selectedChannelId, content, threadRootMessage.Id);
        threadReplies.Add(reply);

        // Update reply count
        threadReplyCounts[threadRootMessage.Id] = threadReplies.Count;
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);

        // Update local state
        var msg = messages.FirstOrDefault(m => m.Id == args.MessageId);
        if (msg is not null)
        {
            var existing = msg.Reactions.FirstOrDefault(r => r.Emoji == args.Emoji);
            if (existing is not null)
            {
                existing.Users.Add("You");
            }
            else
            {
                msg.Reactions.Add(new Reaction(args.Emoji, ["You"]));
            }
        }
    }

    private Task<Dictionary<int, int>> BuildThreadReplyCounts()
    {
        // Build reply counts from messages that are thread starters (have replies referencing them)
        var counts = messages
            .Where(m => m.ReplyToId is not null)
            .GroupBy(m => m.ReplyToId!.Value)
            .ToDictionary(g => g.Key, g => g.Count());

        return Task.FromResult(counts);
    }
}
