toolArgs.file_text:
/* Chat Layout */
::deep .chat-layout {
    display: grid;
    grid-template-columns: 20% 1fr;
    height: 100vh;
    overflow: hidden;
}

::deep .chat-layout.thread-open {
    grid-template-columns: 20% 1fr 25%;
}

/* Channel Sidebar */
::deep .channel-sidebar {
    background: #2b2d31;
    color: #f2f3f5;
    display: flex;
    flex-direction: column;
    border-right: 1px solid #1e1f22;
    overflow: hidden;
}

::deep .sidebar-header {
    padding: 16px;
    border-bottom: 1px solid #1e1f22;
}

::deep .sidebar-header h3 {
    margin: 0;
    font-size: 1rem;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    color: #b5bac1;
}

::deep .channel-list {
    overflow-y: auto;
    flex: 1;
    padding: 8px 0;
}

::deep .channel-item {
    padding: 8px 16px;
    cursor: pointer;
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 4px;
    transition: background-color 0.15s;
}

::deep .channel-item:hover {
    background: #35373c;
}

::deep .channel-item.active {
    background: #404249;
}

::deep .channel-name {
    font-weight: 600;
    font-size: 0.95rem;
    flex: 1;
}

::deep .channel-description {
    width: 100%;
    font-size: 0.75rem;
    color: #949ba4;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

::deep .unread-badge {
    background: #f23f43;
    color: white;
    border-radius: 10px;
    padding: 1px 6px;
    font-size: 0.7rem;
    font-weight: bold;
    min-width: 18px;
    text-align: center;
}

/* Message Area */
::deep .message-area {
    display: flex;
    flex-direction: column;
    background: #313338;
    color: #dbdee1;
    overflow: hidden;
}

::deep .message-area-header {
    padding: 12px 20px;
    border-bottom: 1px solid #3f4147;
    flex-shrink: 0;
}

::deep .message-area-header h2 {
    margin: 0;
    font-size: 1.1rem;
    color: #f2f3f5;
}

::deep .message-area-header p {
    margin: 4px 0 0;
    font-size: 0.8rem;
    color: #949ba4;
}

::deep .no-channel-selected {
    display: flex;
    align-items: center;
    justify-content: center;
    height: 100%;
    color: #949ba4;
}

/* Message List */
::deep .message-list {
    flex: 1;
    overflow-y: auto;
    padding: 16px 20px;
}

::deep .loading-indicator {
    text-align: center;
    padding: 8px;
    color: #949ba4;
    font-size: 0.85rem;
}

::deep .message-bubble {
    padding: 8px 12px;
    border-radius: 4px;
    position: relative;
    margin-bottom: 4px;
}

::deep .message-bubble.hovered {
    background: #2e3035;
}

::deep .message-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 2px;
}

::deep .message-author {
    font-weight: 600;
    font-size: 0.9rem;
    color: #f2f3f5;
}

::deep .message-time {
    font-size: 0.7rem;
    color: #949ba4;
}

::deep .message-content {
    font-size: 0.9rem;
    line-height: 1.4;
    word-wrap: break-word;
}

/* Reactions */
::deep .message-reactions {
    display: flex;
    flex-wrap: wrap;
    gap: 4px;
    margin-top: 6px;
}

::deep .reaction-badge {
    background: #3f4248;
    border: 1px solid #4e5058;
    border-radius: 6px;
    padding: 2px 8px;
    font-size: 0.8rem;
    cursor: pointer;
    transition: background 0.15s;
}

::deep .reaction-badge:hover {
    background: #4e5058;
}

/* Thread Link */
::deep .thread-link {
    color: #00a8fc;
    font-size: 0.8rem;
    cursor: pointer;
    margin-top: 4px;
    font-weight: 500;
}

::deep .thread-link:hover {
    text-decoration: underline;
}

/* Message Actions */
::deep .message-actions {
    position: absolute;
    top: -8px;
    right: 12px;
    display: flex;
    gap: 2px;
    background: #2b2d31;
    border: 1px solid #3f4147;
    border-radius: 4px;
    padding: 2px;
}

::deep .action-btn {
    background: none;
    border: none;
    padding: 4px 6px;
    cursor: pointer;
    font-size: 0.9rem;
    border-radius: 3px;
}

::deep .action-btn:hover {
    background: #3f4147;
}

/* Emoji Picker */
::deep .emoji-picker {
    position: absolute;
    top: -8px;
    right: 80px;
    background: #2b2d31;
    border: 1px solid #3f4147;
    border-radius: 6px;
    padding: 6px;
    display: flex;
    gap: 4px;
    z-index: 10;
}

::deep .emoji-option {
    cursor: pointer;
    font-size: 1.2rem;
    padding: 2px 4px;
    border-radius: 4px;
}

::deep .emoji-option:hover {
    background: #3f4147;
}

/* Message Input */
::deep .message-input {
    display: flex;
    align-items: flex-end;
    gap: 8px;
    padding: 12px 20px;
    border-top: 1px solid #3f4147;
    flex-shrink: 0;
}

::deep .message-input textarea {
    flex: 1;
    background: #383a40;
    border: none;
    border-radius: 8px;
    padding: 10px 14px;
    color: #dbdee1;
    font-size: 0.9rem;
    resize: none;
    outline: none;
    font-family: inherit;
}

::deep .message-input textarea::placeholder {
    color: #6d6f78;
}

::deep .btn-send {
    background: #5865f2;
    color: white;
    border: none;
    border-radius: 6px;
    padding: 10px 16px;
    font-weight: 600;
    cursor: pointer;
    font-size: 0.85rem;
    transition: background 0.15s;
}

::deep .btn-send:hover:not(:disabled) {
    background: #4752c4;
}

::deep .btn-send:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

/* Thread Panel */
::deep .thread-panel {
    background: #2b2d31;
    color: #dbdee1;
    display: flex;
    flex-direction: column;
    border-left: 1px solid #1e1f22;
    overflow: hidden;
}

::deep .thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 12px 16px;
    border-bottom: 1px solid #3f4147;
}

::deep .thread-header h3 {
    margin: 0;
    font-size: 1rem;
    color: #f2f3f5;
}

::deep .btn-close-thread {
    background: none;
    border: none;
    color: #b5bac1;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 4px;
}

::deep .btn-close-thread:hover {
    background: #3f4147;
    color: #f2f3f5;
}

::deep .thread-root-message {
    padding: 12px 16px;
    border-bottom: 1px solid #3f4147;
    background: #232428;
}

::deep .thread-root-message p {
    margin: 4px 0 0;
    font-size: 0.85rem;
    color: #b5bac1;
}

::deep .thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 12px 16px;
}

::deep .thread-reply {
    margin-bottom: 12px;
    padding: 6px 0;
}

